void point2SolidStreak( geometryInS inputs[1], bool isCulled, 
    float lineWidth, float tailSize, 
    float4x4 worldViewProj, float2 screenSize,  
    inout TriangleStream<geometryInS> outStream ) 
{ 
    if( isCulled ) return; 

    geometryInS outS = inputs[0]; 
    float4 length = mul( float4( tailSize * outS.Nw, 0.0f ), worldViewProj ); 
    float2 dir = normalize(length.xy); 
    float4 width = lineWidth  * outS.Pc.w * float4(float2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    outS.Pc = inputs[0].Pc + width; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - width; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length + width; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length - width; 
    outStream.Append( outS ); 
    outStream.RestartStrip(); 
}


void point2SolidStreak( AttribArray<geometryInS> inputs, bool isCulled, 
    float lineWidth, float tailSize, 
    float4x4 worldViewProj, float2 screenSize ) 
{ 
    if( isCulled ) return; 

    geometryInS outS = inputs[0]; 
    float4 length = mul( worldViewProj, float4( tailSize * outS.Nw, 0.0f ) ); 
    float2 dir = normalize(length.xy); 
    float4 width = lineWidth  * outS.Pc.w * float4(float2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    outS.Pc = inputs[0].Pc + width; 
    emitVertex( outS ); 
    outS.Pc = inputs[0].Pc - width; 
    emitVertex( outS ); 
    outS.Pc = inputs[0].Pc - length + width; 
    emitVertex( outS ); 
    outS.Pc = inputs[0].Pc - length - width; 
    emitVertex( outS ); 
    restartStrip(); 
}


void point2SolidStreak(  bool isCulled, 
    float lineWidth, float tailSize, 
    mat4x4 worldViewProj, vec2 screenSize ) 
{ 
    if( isCulled ) return; 

    GEO_OUT_struct outS = copyFromGEO_IN(0); 
    vec4 length = mul( worldViewProj, vec4( tailSize * outS.Nw, 0.0f ) ); 
    vec2 dir = normalize(length.xy); 
    vec4 width = lineWidth  * outS.Pc.w * vec4(vec2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    outS.Pc = gl_in[0].gl_Position + width; 
    EmitGeoStruct( outS ); 
    outS.Pc = gl_in[0].gl_Position - width; 
    EmitGeoStruct( outS ); 
    outS.Pc = gl_in[0].gl_Position - length + width; 
    EmitGeoStruct( outS ); 
    outS.Pc = gl_in[0].gl_Position - length - width; 
    EmitGeoStruct( outS ); 
    EndPrimitive(); 
}


void point2SolidStreak( geometryInS inputs[1], bool isCulled, 
    float lineWidth, float tailSize, 
    float4x4 worldViewProj, float2 screenSize,  
    inout TriangleStream<geometryInS> outStream ) 
{ 
    if( isCulled ) return; 

    geometryInS outS = inputs[0]; 
    float4 length = mul( float4( tailSize * outS.Nw, 0.0f ), worldViewProj ); 
    float2 dir = normalize(length.xy); 
    float4 width = lineWidth  * outS.Pc.w * float4(float2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    outS.Pc = inputs[0].Pc + width; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - width; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length + width; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length - width; 
    outStream.Append( outS ); 
    outStream.RestartStrip(); 
}
